DROP PROCEDURE IF EXISTS [dbxdb].[MultiEntityReconciliationProc];
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [dbxdb].[MultiEntityReconciliationProc]
    AS 
    BEGIN
        SET  XACT_ABORT  ON
        SET  NOCOUNT  ON
		DECLARE @VarSQL nvarchar(max)
		DECLARE @tname nvarchar(max)
		DECLARE @tlist nvarchar(max)
		DECLARE @VarCount INT
        SET @tlist = ''
		SET @VarCount = 1
        DECLARE tableList CURSOR LOCAL
        	FOR (SELECT tablename FROM [dbxdb].[tablelist]);
        OPEN tableList
		FETCH NEXT FROM tableList into @tname
        WHILE (@@FETCH_STATUS=0)
        BEGIN
			SET @VarCount = 0;
            IF EXISTS(SELECT 1 FROM [information_schema].[columns] WHERE column_name = N'companyLegalUnit' AND TABLE_NAME = @tname)
				SET @VarSQL = concat('(SELECT @count = COUNT(DISTINCT companyLegalUnit) FROM [dbxdb].[', @tname, '] where companyLegalUnit =  ''ALL'' or companyLegalUnit =  '''' );');
			ELSE
				SET @VarSQL = concat('(SELECT @count = COUNT(DISTINCT legalEntityId) FROM [dbxdb].[', @tname, '] where legalEntityId =  ''ALL'' or legalEntityId =  '''');');
			EXECUTE SP_EXECUTESQL @VarSQL,N'@count INT output',@count=@VarCount output;
			IF @VarCount = 1 BEGIN
				SET @tlist = CONCAT(@tname,',',@tlist);
			END
        	FETCH NEXT FROM tableList into @tname
        	CONTINUE
        END
		CLOSE tableList
		SELECT @tlist;
   END
GO

DROP PROCEDURE IF EXISTS [dbxdb].[customerDataUpgradeForMultiEntity];
GO
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE OR ALTER PROCEDURE [dbxdb].[customerDataUpgradeForMultiEntity]
    AS 
    BEGIN
    SET  XACT_ABORT  ON
    SET  NOCOUNT  ON

	ALTER TABLE dbxdb.customer NOCHECK CONSTRAINT ALL;
	ALTER TABLE dbxdb.customerlegalentity NOCHECK CONSTRAINT ALL;

	DECLARE @customerid nvarchar(50);
	DECLARE @newLegalEntityId nvarchar(50);
	DECLARE customerIdList CURSOR LOCAL
		FOR (SELECT id from [dbxdb].[customer]);
        OPEN customerIdList
			FETCH NEXT FROM customerIdList into @customerid
       		WHILE (@@FETCH_STATUS=0)
       		BEGIN
				SET @newLegalEntityId = (SELECT companyLegalUnit from [dbxdb].[customer] where id=@customerid);
				UPDATE [dbxdb].[customer] set homeLegalEntity = @newLegalEntityId where id=@customerid;
				FETCH NEXT FROM customerIdList into @customerid
        		CONTINUE
       		END
		CLOSE customerIdList
		DEALLOCATE customerIdList
	ALTER TABLE dbxdb.customer CHECK CONSTRAINT ALL;
	ALTER TABLE dbxdb.customerlegalentity CHECK CONSTRAINT ALL;
   END
GO

DROP PROCEDURE IF EXISTS [dbxdb].[customerUpgradeReconcileProc];
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER   PROCEDURE [dbxdb].[customerUpgradeReconcileProc]
AS
BEGIN
	DECLARE @homeLE nvarchar(255)
	DECLARE @companyLE nvarchar(255)
	DECLARE @customerid nvarchar(255)
	DECLARE @listOfCustomerIds nvarchar(255)
	DECLARE @listOfCustomerEntityIds nvarchar(255)
	DECLARE @entityId nvarchar(255)
	DECLARE @entityIds nvarchar(255)
	DECLARE @notcustomerid nvarchar(255)
	DECLARE @TotalCustomerIds nvarchar(255)
	DECLARE customeridcursor CURSOR LOCAL for (select id from [dbxdb].[customer]);
	DECLARE notCustomerId CURSOR LOCAL for (select id from [dbxdb].[customer] where [dbxdb].find_in_SET(id, @entityIds) > 0);

	OPEN customeridcursor;
	FETCH NEXT FROM customeridcursor INTO @customerid;
	WHILE (@@FETCH_STATUS=0)
	BEGIN
		SET @homeLE = (select homeLegalEntity from [dbxdb].[customer] where id = @customerid);
		SET @companyLE = (select companyLegalUnit from [dbxdb].[customer] where id = @customerid);
		IF (@homeLE != @companyLE) BEGIN
			SET @listOfCustomerIds = CONCAT(@customerid,',',@listOfCustomerIds);
		END
		SET @entityId = (SELECT Customer_id FROM [dbxdb].[customerlegalentity]
					WHERE [dbxdb].[customerlegalentity].Customer_id = @customerid
					AND [dbxdb].[customerlegalentity].legalEntityId =  @companyLE );
		IF (@entityId != '') BEGIN
			SET @entityIds = concat (@entityId, ',', @entityIds);
		END;
		FETCH NEXT FROM customeridcursor INTO @customerid;
		CONTINUE
	END
	CLOSE customeridcursor;
	DEALLOCATE customeridcursor;

	OPEN notCustomerId;
		FETCH NEXT FROM notCustomerId INTO @notcustomerid;
		WHILE (@@FETCH_STATUS=0)
		BEGIN
			SET @listOfCustomerEntityIds = concat(@notcustomerid,',',@listOfCustomerEntityIds);
			FETCH NEXT FROM notCustomerId INTO @notcustomerid;
			CONTINUE
		END
	CLOSE notCustomerId;
	DEALLOCATE notCustomerId;
	SET @TotalCustomerIds = @listOfCustomerIds;
	SET @TotalCustomerIds = concat(@TotalCustomerIds,'~',@listOfCustomerEntityIds);
	SELECT @TotalCustomerIds;
	END
GO

